/** O texto de ANTES desta camada (LF). Lança se um bloco dela não estiver lá exatamente uma vez. */
export function semMaoAjuste1610(rel, text) {
  let s = desfazMaoAjuste3_1610(rel, String(text)) // KINEO-ADS-MAO-AJUSTE-3-1610 — a 3ª rodada sai primeiro (já devolve LF)
  const hunks = DESFAZ[rel]
  if (!hunks) return s
  for (const h of hunks) {
    const now = h.now.join('\n')
    const parts = s.split(now)
    if (parts.length !== 2) throw new Error('semMaoAjuste1610: ' + rel + ' mudou fora desta camada (' + (parts.length - 1) + 'x: ' + now.slice(0, 60) + ')')
    s = parts.join(h.before.join('\n'))
  }
  return s
}
/** Forma tolerante: texto SEM a marca desta camada passa igual (LF) — a base, ou um arquivo fora da lista. null/undefined passa igual. */
export function desfazMaoAjuste1610(rel, text) {
  text = desfazMaoAjuste3_1610(rel, text) // KINEO-ADS-MAO-AJUSTE-3-1610 — a 3ª rodada sai primeiro (null passa igual)
  if (text == null || !DESFAZ[rel] || !String(text).includes(MARCA_MAO_AJUSTE_1610)) return text == null ? text : String(text).replace(/\r\n/g, '\n')
  return semMaoAjuste1610(rel, text)
}
/** A IDA: o texto de antes (LF) com esta camada aplicada. Lança se o bloco de antes não estiver lá exatamente uma vez. */
export function comMaoAjuste1610(rel, text) {
  let s = String(text).replace(/\r\n/g, '\n')
  const hunks = DESFAZ[rel]
  if (!hunks) return s
  for (const h of [...hunks].reverse()) {
    const before = h.before.join('\n')
    const parts = s.split(before)
    if (parts.length !== 2) throw new Error('comMaoAjuste1610: ' + rel + ' não tem o texto de antes (' + (parts.length - 1) + 'x)')
    s = parts.join(h.now.join('\n'))
  }
  return s
}
